CREATE TABLE "Warehouse" ("id" TEXT NOT NULL PRIMARY KEY, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "location" TEXT, "manager" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "Warehouse_code_key" ON "Warehouse"("code");
CREATE TABLE "Supplier" ("id" TEXT NOT NULL PRIMARY KEY, "supplierCode" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT, "phone" TEXT, "website" TEXT, "address" TEXT, "leadTimeDays" INTEGER NOT NULL DEFAULT 0, "preferredSupplier" BOOLEAN NOT NULL DEFAULT false, "rating" REAL NOT NULL DEFAULT 0, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Supplier_supplierCode_key" ON "Supplier"("supplierCode");
CREATE TABLE "SparePart" ("id" TEXT NOT NULL PRIMARY KEY, "partNumber" TEXT NOT NULL, "barcode" TEXT, "qrCode" TEXT, "name" TEXT NOT NULL, "description" TEXT, "manufacturer" TEXT, "category" TEXT NOT NULL, "image" TEXT, "compatibleAssetTypes" TEXT NOT NULL DEFAULT '[]', "unitCost" REAL NOT NULL DEFAULT 0, "reorderLevel" INTEGER NOT NULL DEFAULT 0, "minimumStock" INTEGER NOT NULL DEFAULT 0, "maximumStock" INTEGER NOT NULL DEFAULT 0, "leadTimeDays" INTEGER NOT NULL DEFAULT 0, "supplierId" TEXT, CONSTRAINT "SparePart_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "SparePart_partNumber_key" ON "SparePart"("partNumber");
CREATE UNIQUE INDEX "SparePart_barcode_key" ON "SparePart"("barcode");
CREATE UNIQUE INDEX "SparePart_qrCode_key" ON "SparePart"("qrCode");
CREATE INDEX "SparePart_category_name_idx" ON "SparePart"("category", "name");
CREATE INDEX "SparePart_supplierId_idx" ON "SparePart"("supplierId");
CREATE TABLE "InventoryItem" ("id" TEXT NOT NULL PRIMARY KEY, "warehouseId" TEXT NOT NULL, "sparePartId" TEXT NOT NULL, "quantity" INTEGER NOT NULL DEFAULT 0, "reserved" INTEGER NOT NULL DEFAULT 0, "available" INTEGER NOT NULL DEFAULT 0, "shelf" TEXT, "lastMovementAt" DATETIME, CONSTRAINT "InventoryItem_warehouseId_fkey" FOREIGN KEY ("warehouseId") REFERENCES "Warehouse"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "InventoryItem_sparePartId_fkey" FOREIGN KEY ("sparePartId") REFERENCES "SparePart"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "InventoryItem_warehouseId_sparePartId_key" ON "InventoryItem"("warehouseId", "sparePartId");
CREATE INDEX "InventoryItem_sparePartId_quantity_idx" ON "InventoryItem"("sparePartId", "quantity");
CREATE TABLE "WorkOrderPart" ("id" TEXT NOT NULL PRIMARY KEY, "workOrderId" TEXT NOT NULL, "inventoryItemId" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "deductedAt" DATETIME, CONSTRAINT "WorkOrderPart_workOrderId_fkey" FOREIGN KEY ("workOrderId") REFERENCES "WorkOrder"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "WorkOrderPart_inventoryItemId_fkey" FOREIGN KEY ("inventoryItemId") REFERENCES "InventoryItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "WorkOrderPart_workOrderId_inventoryItemId_key" ON "WorkOrderPart"("workOrderId", "inventoryItemId");
CREATE INDEX "WorkOrderPart_workOrderId_deductedAt_idx" ON "WorkOrderPart"("workOrderId", "deductedAt");
CREATE TABLE "StockMovement" ("id" TEXT NOT NULL PRIMARY KEY, "inventoryItemId" TEXT NOT NULL, "destinationInventoryItemId" TEXT, "assetId" TEXT, "workOrderId" TEXT, "movementType" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "balanceAfter" INTEGER NOT NULL, "performedBy" TEXT NOT NULL, "reference" TEXT, "notes" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "StockMovement_inventoryItemId_fkey" FOREIGN KEY ("inventoryItemId") REFERENCES "InventoryItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "StockMovement_assetId_fkey" FOREIGN KEY ("assetId") REFERENCES "Asset"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "StockMovement_inventoryItemId_createdAt_idx" ON "StockMovement"("inventoryItemId", "createdAt");
CREATE INDEX "StockMovement_workOrderId_createdAt_idx" ON "StockMovement"("workOrderId", "createdAt");
CREATE INDEX "StockMovement_assetId_createdAt_idx" ON "StockMovement"("assetId", "createdAt");
